        "knowledge": "图形规律和数字规律道理一样，只是把\"数\"换成了\"图形\"或\"颜色\"。常见两种：一是几个图形一组反复循环（如 △○△○…），二是每组数量依次增加（1个、2个、3个…）。找到\"几个一循环\"或\"每次多几个\"，就能知道下一个是什么。",
        "method": [
          "**口诀：\"图形排队找循环，几组一轮记在心；第几个就数一数，除不尽时看余数。\"**",
          "**循环规律**：看几个图形一组，用「第几个 ÷ 每组几个」看余数。整除就是这组的最后一个，余几就是这组的第几个。",
          "**数量规律**：看每组图形个数是不是 1、2、3、4 这样依次加 1。"
        ],
        "examples": [
          {
            "t": "",
            "b": ""
          },
          {
            "t": "例题1（L1 第18题）**：珠子按\"红、黄、蓝、红、黄、蓝……\"排列，第 9 颗是什么颜色？",
            "b": "- \"红黄蓝\"3 个一组循环。\n\n- 9÷3=3，正好除尽（余 0），说明第 9 颗是第 3 组的最后一个——蓝色。\n\n- **答案：蓝**。"
          },
          {
            "t": "",
            "b": ""
          },
          {
            "t": "例题2（L1 第21题）**：○，△，□，○，△，□，____。填什么？",
            "b": "- \"圆、三角、方\"3 个一组循环。\n\n- 第 7 个：7÷3=2 余 1，是下一组的第 1 个——○。\n\n- **答案：○**。"
          },
          {
            "t": "",
            "b": ""
          },
          {
            "t": "例题3（L1 第17题）**：□，□□，□□□，____。第四个图形有几个小正方形？",
            "b": "- 每组小正方形个数是 1、2、3，每次多 1，第 4 组是 4 个。\n\n- **答案：C（4个）**。"
          }
        ],
