        "knowledge": "\"分类\"就是看哪一样东西和别的不一样——找\"不同类\"时，先看大部分东西属于哪一类（文具、水果、动物…），哪个不属于这一类就是答案。\"比较\"就是把几个数排排队，分清\"从大到小\"还是\"从小到大\"。",
        "method": [
          "**口诀：\"找同类先归类，异类一眼挑出来；排序先比最大最小，再依次排好队。\"**",
          "**不是同类**：先给三个同类找共同点（都是水果/文具/蔬菜），剩下的就是异类。",
          "**排序**：先圈出最大（或最小），再依次排。"
        ],
