        "knowledge": "\"比较推理\"就是根据几句话，推出一群东西谁最大、谁最快、谁最重。\"甲比乙高、乙比丙高\"这类话可以像接力棒一样传下去：甲>乙>丙，于是甲最高。有时还要加上\"谁在什么位置\"的位置信息来推。",
        "method": [
          "**口诀：\"比高比快用箭头，一长串连起来；最高的排最前，最矮的排最后；位置题画格子，一格一格填清楚。\"**",
          "**传递比较**：把\"甲>乙、乙>丙\"连成\"甲>乙>丙\"。",
          "**位置/对应**：画一排格子，把已知的放进去，剩下的就确定了。"
        ],
