        "knowledge": "排队问题是小学奥数经典题。核心一句话：算总人数时别把\"自己\"漏掉。常见三类：①前有几人、后有几人，求总数；②从左数第几、从右数第几，求总数；③两人之间隔几人。",
        "method": [
          "**口诀：\"前面 + 后面 + 自己 = 总数；从左第几 + 从右第几 - 1 = 总数；两人中间 = 大序号 - 小序号 - 1。\"**",
          "**求总数（有前后人数）**：前面 + 后面 + 1（自己）。",
          "**求总数（左数第几、右数第几）**：左数 + 右数 - 1（自己数了两次）。",
          "**从后面数第几**：总数 - 从前面第几 + 1。",
          "**两人之间几人**：序号大 - 序号小 - 1。"
        ],
