        "method": [
          "**口诀：\"每行每列每个宫，数字一个不能重；看看已经有哪些，缺的那个往里填。\"**",
          "**规则**：行、列、宫都要含 1~N 且不重复。",
          "**唯一法**：某行/列/宫已有 N-1 个不同数字，缺的那个就是答案。"
        ],
