          "**求\"至少几个\"**：总数 ÷ 抽屉数，有余数就\"商 +1\"（如 8 个苹果放 3 个抽屉，8÷3=2 余 2，至少 3 个）。",
          "**保证摸到同色**：颜色种类 +1 个就保证有同色（如 3 种颜色，摸 4 个保证有同色）。"
