        "knowledge": "取物游戏（火柴、石子、报数）的核心是\"凑数\"：每次最多取 n 个，那么\"安全数\"就是 n+1。只要让每轮你和对手一共凑成 n+1，就能控制局面、拿到最后一个。",
        "method": [
          "**口诀：\"最多取 n，安全数是 n+1；总数除以 n+1 看余数，有余数先取余数，没余数后手赢；然后每轮跟对手凑成 n+1。\"**",
          "**取到最后一个赢**：安全数 = 每次最多取数 +1。总数 ÷ 安全数看余数：余数 > 0 先手取余数、之后凑安全数；整除则后手必胜。",
          "**取到最后一个输**（反过来）：把\"最后一枚\"留给对手，安全数同理，先手要处理\"总数 -1\"。"
        ],
