        "knowledge": "\"比较多少\"就是问\"谁比谁多多少\"或\"谁比谁少多少\"。这类题的核心只有一个动作：**用大数减小数**，得到的差就是\"多出来（或少出来）的那部分\"。反过来，如果已知一个数和它\"比另一个数多几/少几\"，也能求出另一个数。",
        "method": [
          "求\"**A比B多几/少几**\"：`多的 − 少的 = 相差数`",
          "求\"**比一个数多几的数**\"：用加法，`这个数 + 几`",
          "求\"**比一个数少几的数**\"：用减法，`这个数 − 几`",
          "**口诀**：比多比少，大减小；比……多几就加，比……少几就减。"
        ],
