        "method": [
          "两位数 ab = **10a＋b**；三位数 abc = **100a＋10b＋c**。",
          "交换两位数的十位和个位：ab 与 ba 的差 = **(10a+b)−(10b+a) = 9(a−b)**。",
          "口诀「**十位乘十，百位乘百；交换做差，九个差**」。"
        ],
