            "t": "例 1**（题库第 148 题）：用数字 a、b 组成两位数 ab 和 ba，它们的差（ab−ba）等于？",
            "b": "**分步解析**：\n\n1. ab = 10a＋b，ba = 10b＋a。\n\n2. ab−ba = (10a＋b)−(10b＋a) = 10a＋b−10b−a = 9a−9b = **9(a−b)**。\n\n3. 选 A。\n\n\n\n**为什么**：十位和个位交换，十位的贡献差了 9 倍的数字差。"
