            "b": "- **第一步，找已知**：车长 200 米，桥长 600 米，速度 20 米/秒。\n\n- **第二步，先求总路程**：车长 + 桥长 = 200 + 600 = 800（米）。这是火车从车头上桥到车尾离桥一共要走的路。\n\n- **第三步，求时间**：800 ÷ 20 = 40（秒）。\n\n- **答**：需要 40 秒。选 C。\n\n\n\n> 为什么加车长？如果只算桥长600米，那是\"车头从桥头到桥尾\"，但这时车身还有200米没过去，所以必须再多走200米。"
