        "knowledge": "环形跑道就是把\"直线\"弯成一个圈。两个人从**同一个点**出发，有两种走法：\n\n\n\n- **同向出发（一个方向追）**：一个快一个慢，快的要\"套圈\"追上慢的。追上时，快的比慢的**正好多跑一整圈**。所以这时候的\"路程差\"就是**跑道一圈的长度（周长）**。\n\n- **相向（反向）出发**：两人背对背各走各的，第一次碰头时，两人合起来**正好走完一整圈**。所以这时候的\"路程和\"就是**周长**。\n\n\n\n看懂这一点，环形跑道就变成前面学过的\"追及\"和\"相遇\"了。",
