            "b": "- **第一步，判断类型**：同向出发，是\"追及\"问题。\n\n- **第二步，想清楚路程差**：甲第一次追上乙时，甲比乙多跑一圈，即 400 米。\n\n- **第三步，求速度差**：6 - 4 = 2（米/秒）。\n\n- **第四步，求时间**：400 ÷ 2 = 200（秒）。\n\n- **答**：200 秒后甲第一次追上乙。选 B。\n\n\n\n> 为什么是\"多跑一圈\"？两人从同一点出发，甲要重新和乙并肩，必须绕场一圈比乙多跑 400 米。"
