        "knowledge": "船在水里开，除了船自己（发动机/划桨）的速度，还要看**水流**帮不帮忙。\n\n\n\n- **静水速度**：没有水流时船自己开的速度（也叫\"船速\"）。\n\n- **水速**：水流的速度。\n\n- **顺水速度**：顺着水流方向开，水流在后面推着船走，所以更快：顺水 = 静水 + 水速。\n\n- **逆水速度**：逆着水流方向开，水流挡着船，所以更慢：逆水 = 静水 - 水速。\n\n\n\n想象成你跑步：顺风跑会快一点（风帮了你），逆风跑会慢一点（风挡着你）。水流就相当于\"风\"。",
