          "**水速 =（顺水速度 - 逆水速度）÷ 2** > 记法口诀：**\"顺水加、逆水减，求静水取平均（加），求水速取半差（减）。\"** > 核心一句：**顺 = 静 + 水；逆 = 静 - 水**。后面两个公式是\"和差问题\"——(顺+逆)÷2 求静水，(顺-逆)÷2 求水速。"
