            "t": "例1（题库第173题）**：一辆车以每小时60千米行2小时，再以每小时90千米行1小时，平均速度是多少？",
            "b": "- **第一步，先求总路程**：第一段 60×2 = 120 千米，第二段 90×1 = 90 千米，总路程 = 120 + 90 = 210 千米。\n\n- **第二步，再求总时间**：2 + 1 = 3 小时。\n\n- **第三步，求平均速度**：210 ÷ 3 = 70（千米/时）。\n\n- **答**：平均速度是 70 千米/时。选 B。\n\n\n\n> 注意：不能直接 (60+90)÷2 = 75，那是错的！因为两个速度跑的时间不一样长。"
