            "b": "- **第一步，判断类型**：前一半、后一半路程一样长，速度分别是 60 和 40。\n\n- **第二步，用往返同程公式**：平均速度 = 2ab ÷ (a+b) = 2×60×40 ÷ (60+40) = 4800 ÷ 100 = 48（米/分）。\n\n- **答**：全程平均速度是 48 米/分。选 B。\n\n\n\n> 为什么不是 (60+40)÷2=50？因为前一半路用60的速度走得快（花时间少），后一半用40走得慢（花时间多），整体被慢的那段\"拖累\"，所以平均速度低于50，是48。"
