            "b": "- **第一步，求总路程**：上山6千米 + 下山6千米 = 12 千米。\n\n- **第二步，分别求时间**：上山 6÷3 = 2 小时；下山 6÷6 = 1 小时；总时间 = 2 + 1 = 3 小时。\n\n- **第三步，求平均速度**：12 ÷ 3 = 4（千米/时）。\n\n- **答**：平均速度是 4 千米/时。选 B。\n\n\n\n> 也可以直接用公式 2×3×6÷(3+6) = 36÷9 = 4，结果一样。"
