            "b": "- **第一步，回忆规律**：第一次相遇合走 1 个全程。\n\n- **第二步，第二次相遇**：第一次相遇后，两人继续走到头再返回，又合走 2 个全程，所以一共 1 + 2 = 3 个全程。\n\n- **答**：一共走了 3 个全程。选 C。\n\n\n\n> 直观理解：第二次相遇时，两人相当于\"把这条路来回各走了一遍半\"，合起来正好3个全程。"
