            "b": "- **第一步，先求第二次相遇的合走总路程**：3 × 28 = 84 千米。\n\n- **第二步，算甲占的比例**：甲速度8、乙速度6，速度比 8:6 = 4:3，所以甲走的路占 4/(4+3) = 4/7。\n\n- **第三步，求甲走的路**：84 × 4/7 = 48 千米。\n\n- **答**：第二次相遇时甲走了 48 千米。选 C。\n\n\n\n> 技巧：两人合走的路程按速度比分，就能算出各自走了多少。"
