        "practice": "- 题库题号：**186～200**\n\n- 重点练：题186、187、189、191、196、198（全程数规律）；题188、190、192、197（算各自/总路程）；题193、195、199、200（已知相遇点求全程，最难）；题194（判断题）。\n\n\n\n---\n\n\n\n## 附：本专题公式速查表\n\n\n\n| 类型 | 核心公式 | 口诀 |\n\n|------|---------|------|\n\n| 基本行程 | 路程=速度×时间 | 求路程相乘，求速度/时间相除 |\n\n| 相遇 | 相遇时间=路程÷速度和 | 相向用\"和\" |\n\n| 追及 | 追及时间=路程差÷速度差 | 同向追用\"差\" |\n\n| 火车过桥 | 总路程=车长+桥长 | 过桥别忘了加自己 |\n\n| 环形跑道 | 同向:周长÷速度差；相向:周长÷速度和 | 一圈：追用差、碰用和 |\n\n| 流水行船 | 顺=静+水；逆=静-水 | 顺加逆减 |\n\n| 钟面问题 | 追及时间=夹角÷5.5 | 分针6度、时针0.5度，差5.5度 |\n\n| 比例行程 | 路程一定→速时反比 | 路程一定反着比 |\n\n| 变速变道 | 平均速度=总路程÷总时间 | 别求平均数 |\n\n| 多次相遇 | 第n次相遇合走(2n-1)个全程 | 一次一全程，二次三全程 |\n\n\n\n---\n\n\n\n> 完。学完讲义后，请按每个单元\"🔗 配套练习\"标注的题号，去《行程问题专题题库（200题）》中刷题巩固。",
